 "new_string": "/**
 * ADR-0005 repair queue: reports depth and outcome counts. Informational
 * only (always passes): a nonzero pending/degraded count reflects real
 * acquisition noise, not a defect in the store itself, so it should not
 * fail doctor the way the other checks (which detect actual drift/corruption) do.
 */
function checkRepairQueue(db: Database.Database): DoctorCheckResult {
  const rows = db.prepare(`SELECT status, COUNT(*) AS n FROM repair_queue GROUP BY status`).all() as
    Array<{ status: string; n: number }>;
  const byStatus = new Map(rows.map(r => [r.status, r.n]));
  const pending  = byStatus.get('pending')  ?? 0;
  const repaired = byStatus.get('repaired') ?? 0;
  const degraded = byStatus.get('degraded') ?? 0;
  const total    = pending + repaired + degraded;

  return {
    name:   'repair-queue',
    passed: true,
    detail: `${total} queued total (${pending} pending, ${repaired} repaired, ${degraded} degraded)`,
  };
}

